"""Mock v59 (SCOPE §86): the three boards in one page that opens from disk. Usage: python3 build_mock.py <out dir>. index.html embeds headshots, so it stays out of the public repo."""
import base64, io, os, sys
from PIL import Image
here = os.path.dirname(os.path.abspath(__file__)); OUT = sys.argv[1]
def uri(p):
    im = Image.open(p).convert('RGB').resize((864, 1080), Image.LANCZOS); b = io.BytesIO(); im.save(b, 'JPEG', quality=87, optimize=True); return 'data:image/jpeg;base64,' + base64.b64encode(b.getvalue()).decode()
P = [('rtd', '', 'Rushing TDs'), ('rec', '-nophoto', 'Receptions'), ('sacks', '-nophoto', 'Most sacks by a defense')]
def grid(th): return ''.join(f'<figure><img src="{uri(os.path.join(OUT, k + "-" + th + s + ".png"))}" alt="{n} board, {th} look"><figcaption>{n}</figcaption></figure>' for k, s, n in P)
css = ''':root{--bg:#f4f1ea;--ink:#121417;--mut:#62666f;--line:#d9d4c8}*{box-sizing:border-box}html,body{background:var(--bg)}body{margin:0;color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif}main{max-width:1180px;margin:0 auto;padding:32px 16px 72px}h1{font-size:28px;line-height:1.2;margin:0 0 8px}p{margin:0 0 14px;max-width:760px}.mu{color:var(--mut)}input{position:absolute;opacity:0}.sw{display:inline-flex;border:1px solid var(--ink);margin:6px 0 20px}.sw label{padding:7px 22px;cursor:pointer;font-weight:600}#k:checked~.sw label[for=k],#p:checked~.sw label[for=p]{background:var(--ink);color:#fff}#k:focus-visible~.sw,#p:focus-visible~.sw{outline:2px solid #cb2026;outline-offset:2px}.g{display:none;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}#k:checked~.a,#p:checked~.b{display:grid}figure{margin:0;min-width:0}img{display:block;width:100%;height:auto}figcaption{padding-top:8px;font-weight:600}@media(max-width:760px){.g{grid-template-columns:minmax(0,1fr)}}'''
page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>More league boards</title><style>{css}</style></head><body><main><h1>Three more league boards</h1><p class="mu">Real numbers through Week 10, at the same 1080 × 1350 size as League Leaders. The sacks board counts every sack a defense recorded, and keeps all four teams tied at 26.</p><input type="radio" name="look" id="k" checked aria-label="Black look"><input type="radio" name="look" id="p" aria-label="Paper look"><div class="sw"><label for="k">Black</label><label for="p">Paper</label></div><div class="g a">{grid('black')}</div><div class="g b">{grid('paper')}</div></main></body></html>'''
open(os.path.join(here, 'index.html'), 'w').write(page); print('ok', round(len(page) / 1048576, 1), 'MB')
